class CartCollection {
    _carts;
    constructor() {
        this._carts = [];
    }
    addCart(cart) {
        this._carts.push(cart);
    }
    addCarts(carts) {
        carts.forEach((c, i, ca) => {
            this._carts.push(c);
        });
    }
    getCarts() {
        return this._carts;
    }
    getCartById(id) {
        return this._carts[id];
    }
}
export default CartCollection;
